tasks.check:
set -o pipefail
[ -e .venv ] || ln -s /home/bcorfman/dev/freytag-forge/.venv .venv
export PYTHONPATH=$PWD:$PWD/packages/worldkeeper/src TMPDIR=/tmp
PY=.venv/bin/python
D=data/stories/continuity-initiative
CH=$(git status --porcelain | grep -v '^?? .venv' | awk '{print $2}' | sort)
[ -n "$CH" ] || { echo "WHY: nothing changed"; exit 1; }
for f in $CH; do case "$f" in $D/knowledge.yaml|tests/*) ;; *) echo "WHY: edited file outside ownership: $f"; exit 1;; esac; done
test "$(git diff HEAD --numstat -- $D/knowledge.yaml | awk '{print $1+$2}')" = "4" || { echo "WHY: knowledge.yaml must change exactly two lines"; exit 1; }
grep -c "Kristin and Michelle have reunited\. Michelle coordinates the prisoners through stolen radios and coded announcements\.$\|Kristin and Michelle have reunited\. Michelle coordinates the prisoners through stolen radios and coded announcements\.'$" $D/knowledge.yaml | grep -qx 1 || { echo "WHY: new A-r1 statement not exactly as specified"; exit 1; }
grep -c "Michelle has explained that freeing this block means little without exposing the other sites\.'\?$" $D/knowledge.yaml | grep -qx 1 || { echo "WHY: new A-r2 statement not exactly as specified"; exit 1; }
grep -n "share one unhurried moment before Michelle returns\|Michelle shares one unhurried moment with Kristin, then explains" $D/knowledge.yaml && { echo "WHY: old statement remains in knowledge.yaml"; exit 1; }
git diff HEAD --quiet -- $D/handoffs.yaml $D/plot.md || { echo "WHY: handoffs.yaml or plot.md edited"; exit 1; }
$PY -m pytest -q -p no:cacheprovider tests/test_richer_3a.py tests/test_knowledge_projection.py tests/test_speaker_lines.py tests/test_prompt_budget.py tests/test_prompt_presence.py tests/test_prompt_inert_lines.py tests/test_markdown_story_package.py tests/test_package_audit.py tests/test_scene_roleplay_contract.py tests/test_knowledge_leakage_matrix.py tests/test_speaker_presence.py tests/test_spine_expected_reveals.py tests/test_3ab_spine_prompts.py tests/test_3a_records_followup.py tests/test_late_scene_repro.py tests/test_discovery_continuity.py > /tmp/td1.out 2>&1; rc=$?; tail -25 /tmp/td1.out; [ $rc -eq 0 ] || { echo "WHY: suites failed"; exit 1; }
PYF=$(echo "$CH" | grep '\.py$' || true)
if [ -n "$PYF" ]; then
  $PY -m ruff check $PYF || { echo "WHY: ruff check failed"; exit 1; }
  $PY -m ruff format --check $PYF || { echo "WHY: ruff format failed"; exit 1; }
fi
git add -A && git diff --cached > /home/bcorfman/dev/ringer-work/3a-open-issues-stepD1/D1-edit.patch && wc -l /home/bcorfman/dev/ringer-work/3a-open-issues-stepD1/D1-edit.patch && git diff --cached --stat | tail -8

